(() => {
 const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const paths={arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',car:'<path d="m4 10 2-6h12l2 6M3 10h18v8H3Zm2 8v3m14-3v3M6 14h2m8 0h2"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h.01M12 15h.01M15 15h.01"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',phone:'<path d="M5 4h4l2 5-3 2a16 16 0 0 0 5 5l2-3 5 2v4c-8 2-18-8-15-15Z"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 7 9 6 9-6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',edit:'<path d="m15 4 5 5M4 20l4-1L21 6l-5-5L3 14Z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',wheel:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/><path d="M3 10h6m6 0h6m-9 5v6"/>',plus:'<path d="M12 5v14M5 12h14"/>'};
 const svg=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[k]||paths.arrow}</svg>`;
 const iconBox=k=>`<span class="action-icon" aria-hidden="true">${svg(k)}</span>`;
 const button=(text,attr='',kind='primary',icon='arrow')=>`<button class="button ${kind} td-button" ${attr}><span>${text}</span>${iconBox(icon)}</button>`;
 const stages=[['Your car','car'],['Your visit','calendar'],['Your details','user'],['Review','check']];
 let core,models=[],locations=[],state,promise,pendingContext='',mountedRoot=null;
 function load(){return promise||(promise=Promise.all([fetch('data/vehicle-library.json').then(r=>{if(!r.ok)throw Error();return r.json()}),import('./test-drive-core.mjs')]).then(([data,c])=>{core=c;models=data.models;locations=(window.uniCarsContactLocations||[]).map((l,i)=>({...l,id:'showroom-'+i}));if(!locations.length)throw Error('locations');state=state||core.freshRequest();return data}).catch(err=>{promise=null;throw err}));}
 function model(){return core.chosenModel(models,state)}
 function location(){return locations.find(l=>l.id===state.locationId)}
 const err=k=>`<p class="td-field-error" id="td-error-${k}" ${state.errors[k]?'role="alert"':''}>${e(state.errors[k]||'')}</p>`;
 const invalid=k=>state.errors[k]?`aria-invalid="true" aria-describedby="td-error-${k}"`:'';
 async function selectContext(context){if(!context)return;if(context.startsWith('smart-vehicle-ehub-'))context='ehub-car-'+context.slice('smart-vehicle-ehub-'.length);let m=models.find(m=>m.id===context||'range-'+m.id===context);if(!m&&context.startsWith('smart-vehicle-'))m=models.find(m=>m.versions.some(v=>'smart-vehicle-'+v.id===context));if(!m&&context.startsWith('model-')){const aliases={'vw-tiguan':'volkswagen-tiguan','vw-taigo':'volkswagen-taigo','vw-t-cross':'volkswagen-t-cross','vw-t-roc':'volkswagen-t-roc'};m=models.find(m=>m.id===(aliases[context.slice(6)]||context.slice(6)))}
  if(!m&&context.startsWith('ehub-car-')){const r=await fetch('data/ehub.json');if(!r.ok)throw Error('stock');const data=await r.json(),offer=data.models.find(m=>'ehub-car-'+m.id===context);if(offer){m={id:'offer-'+offer.id,brand:offer.brand,model:offer.displayModel||offer.model,images:offer.images,offer:true,reference:offer.reference};if(!models.some(x=>x.id===m.id))models=[...models,m]}}
  if(m){state.brand=m.brand;state.modelId=m.id;state.query='';state.limit=Math.max(6,models.filter(x=>x.brand===m.brand).findIndex(x=>x.id===m.id)+1);if(!core.eligibleLocations(locations,m.brand).some(l=>l.id===state.locationId))state.locationId='';state.step=0;state.complete=false;state.errors={};}}
 window.startUniTestDrive=context=>{pendingContext=context||'';if(locationHash()==='#test-drive'){mount()}else window.location.hash='test-drive'};
 const locationHash=()=>window.location.hash;
 window.renderUniTestDrive=route=>{const q=new URLSearchParams((route||'').split('?')[1]||'');if(q.get('model'))pendingContext=q.get('model');queueMicrotask(mount);return '<div class="td-page" id="testDrivePage"><div class="td-loading" role="status">Preparing your test drive…</div></div>'};
 async function mount(){const root=document.getElementById('testDrivePage');if(!root)return;try{await load();if(!root.isConnected)return;const context=pendingContext;pendingContext='';if(context)await selectContext(context);if(!root.isConnected)return;if(mountedRoot!==root){bind(root);mountedRoot=root}draw(root,true);}catch(error){if(root.isConnected)root.innerHTML=`<div class="td-loading"><h1>Let’s arrange your drive.</h1><p>The vehicle selector could not load. Our team can help you choose a car.</p><a class="button primary" href="#contact">Contact Unicars${iconBox('phone')}</a></div>`}}
 function progress(){return `<nav class="td-progress" aria-label="Test drive request progress">${stages.map(([title,icon],i)=>`<button type="button" class="td-progress-step ${i===state.step?'is-current':''} ${i<state.step?'is-complete':''}" data-td-step="${i}" ${i>state.furthest?'disabled':''} ${i===state.step?'aria-current="step"':''}><span class="td-progress-icon">${svg(i<state.step?'check':icon)}</span><span>${title}</span></button>`).join('')}</nav><div class="td-progress-track" aria-hidden="true"><span style="width:${(state.step+1)*25}%"></span></div>`}
 function selection(){const m=model(),l=location();return `<div class="td-selection"><p class="td-overline">${m?'YOUR DRIVE, TAKING SHAPE':'A GOOD PLACE TO START'}</p>${m?`<div class="td-selection-model"><span class="td-selection-logo"><img src="assets/brands/${core.brandLogos[m.brand]}.svg" alt="" width="44" height="34"></span><div><p>${e(m.brand)}</p><h2>${e(m.model)}</h2>${m.offer?`<small>eHub car · ${e(m.reference)}</small>`:''}</div></div>`:`<h2>Five brands.<br>Your kind of drive.</h2>`}<div class="td-selection-visit">${l?`<span>${svg('pin')}${e(l.city)} · ${e(l.name)}</span>`:`<span>${svg('pin')}Your local Unicars team</span>`}${state.date?`<span>${svg('calendar')}${e(core.formatDay(state.date))}${state.period?' · '+e(core.periods[state.period]):''}</span>`:`<span>${svg('wheel')}Choose the car. Experience the feeling.</span>`}</div></div>`}
 function page(){return `<div class="td-wrap"><div class="td-topline"><a class="button secondary td-back-home" href="#cars"><span>Explore vehicles</span>${iconBox('car')}</a><span>${svg('shield')}Your next step, at your pace.</span></div><div class="td-layout"><aside class="td-story"><div class="td-story-photo"><img src="assets/test-drive-driver.webp" alt="A person fastening their seat belt before a drive" width="1024" height="1536"><div class="td-photo-shade"></div><div class="td-story-copy"><p class="td-story-eyebrow">${svg('wheel')}BOOK A TEST DRIVE</p><h1>Good on paper.<br>Better in person.</h1><p>Meet your next car.<br>From the driver’s seat.</p></div>${selection()}</div><p class="td-story-note">${svg('check')}Your car and appointment will be confirmed by the team.</p></aside><section class="td-booking" aria-label="Plan your test drive">${state.complete?'':progress()}<div id="tdStage" class="td-stage" tabindex="-1">${state.complete?complete():stage()}</div></section></div><section class="td-after" aria-labelledby="tdAfterTitle"><div><p class="td-overline">FROM INTEREST TO IGNITION</p><h2 id="tdAfterTitle">A clearer next step.</h2></div><div class="td-after-items"><article>${svg('car')}<h3>Choose your drive</h3><p>Pick the model you’d like to get to know.</p></article><article>${svg('phone')}<h3>Talk to your team</h3><p>Unicars confirms the car, date and location.</p></article><article>${svg('wheel')}<h3>Make it personal</h3><p>Experience the car and ask the questions that matter.</p></article></div></section><p class="td-page-note">Interactive prototype. No request is sent or appointment reserved. Vehicle choices use the published catalogue; test-drive availability needs confirmation.</p></div>`}
 function draw(root,animate=false,focusId){root.innerHTML=page();if(animate)root.querySelector('#tdStage')?.classList.add('td-enter');if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});}
 function heading(kicker,title,copy){return `<div class="td-stage-heading"><p class="td-overline">${kicker}</p><h2 id="tdStepTitle" tabindex="-1">${title}</h2><p>${copy}</p></div>`}
 function footer(){return `<div class="td-form-bottom">${state.step>0?button('Back','type="button" data-td-back','secondary','back'):`<span class="td-small-note">${svg('shield')}No details needed yet.</span>`}${button(state.step===3?'Preview my request':'Continue','type="submit"','primary',state.step===3?'check':'arrow')}</div><p class="td-preview-note">${state.step===3?'Preview only. Your details stay on this page; no request will be sent.':'Your preferred car, date and time are subject to confirmation.'}</p>`}
 function stage(){return `<form id="testDriveForm" novalidate>${state.step===0?carStage():state.step===1?visitStage():state.step===2?detailsStage():reviewStage()}${footer()}</form>`}
 function carStage(){return `${heading('START WITH A FEELING','What would you like to drive?','A familiar favourite or something new. Start with a brand.')}<fieldset class="td-brand-field"><legend class="td-sr">Choose your brand</legend><div class="td-brand-grid">${Object.entries(core.brandLogos).map(([b,file])=>`<label class="td-brand-option"><input id="td-brand-${file}" type="radio" name="brand" value="${e(b)}" ${state.brand===b?'checked':''} ${invalid('brand')}><span><img src="assets/brands/${file}.svg" alt="" width="56" height="38"><strong>${e(b)}</strong></span></label>`).join('')}</div>${err('brand')}</fieldset><div class="td-model-toolbar"><label for="tdModelSearch">${state.brand?'Explore '+e(state.brand):'Explore the range'} <span id="tdModelCount"></span></label><div class="td-search">${svg('search')}<input id="tdModelSearch" type="search" value="${e(state.query)}" placeholder="Find a model" autocomplete="off" aria-label="Search vehicle models"></div></div><fieldset class="td-model-field"><legend class="td-sr">Choose your model</legend><div id="tdModels" class="td-model-grid">${modelGrid()}</div>${err('modelId')}</fieldset><div id="tdMore">${moreModels()}</div>`}
 function modelGrid(){const found=core.modelChoices(models,state),visible=found.slice(0,state.limit);return visible.length?visible.map(m=>`<label class="td-model-option"><input id="td-model-${e(m.id)}" type="radio" name="modelId" value="${e(m.id)}" ${state.modelId===m.id?'checked':''} ${invalid('modelId')}><span class="td-model-surface"><span class="td-model-check">${svg('check')}</span><img src="${e(m.images[0].src)}" alt="${e(m.brand+' '+m.model)} model illustration" width="300" height="170" loading="lazy" class="${m.offer?'is-offer':''}"><span class="td-model-name"><small>${e(m.brand)}</small><strong>${e(m.model)}</strong></span>${m.offer?'<span class="td-model-caption">Selected eHub car</span>':''}</span></label>`).join(''):`<div class="td-no-models"><p>No models match “${e(state.query)}”.</p>${button('Clear search','type="button" data-td-clear','secondary','search')}</div>`}
 function moreModels(){const n=core.modelChoices(models,state).length;return n>state.limit?`<div class="td-more-models"><span>Showing ${Math.min(state.limit,n)} of ${n} models</span>${button('More models','type="button" data-td-more','secondary','plus')}</div>`:`<p class="td-image-note">Model images are illustrative. The team will confirm the available test-drive car.</p>`}
 function calendar(){const today=core.dayKey(),max=core.addDays(today,90).slice(0,7),prev=core.moveMonth(state.month,-1),next=core.moveMonth(state.month,1),title=new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(state.month+'-01T12:00:00Z'));return `<div class="td-calendar"><div class="td-calendar-head"><h3 id="tdCalendarTitle" aria-live="polite">${title}</h3><div><button type="button" class="td-calendar-nav" data-td-month="-1" aria-label="Previous month" ${prev<today.slice(0,7)?'disabled':''}>${svg('back')}</button><button type="button" class="td-calendar-nav" data-td-month="1" aria-label="Next month" ${next>max?'disabled':''}>${svg('arrow')}</button></div></div><div class="td-weekdays" aria-hidden="true">${['M','T','W','T','F','S','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="td-calendar-days" role="group" aria-labelledby="tdCalendarTitle">${core.calendarCells(state.month).map(key=>key?`<label class="td-day"><input type="radio" name="date" id="td-date-${key}" value="${key}" ${state.date===key?'checked':''} ${!core.validDay(key,today)?'disabled':''} aria-label="${e(core.formatDay(key))}" ${invalid('date')}><span>${Number(key.slice(-2))}</span></label>`:'<span></span>').join('')}</div></div>`}
 function visitStage(){const eligible=core.eligibleLocations(locations,state.brand);return `${heading('MAKE ROOM FOR A DRIVE','Where shall we meet?','Choose a sales location and tell us when suits you.')}<fieldset class="td-location-field"><legend>Preferred location <span>For ${e(state.brand)}</span></legend><div class="td-locations">${eligible.map(l=>`<label class="td-location-option"><input id="td-location-${l.id}" type="radio" name="locationId" value="${l.id}" ${state.locationId===l.id?'checked':''} ${invalid('locationId')}><span class="td-location-surface"><span class="td-location-icon">${svg('pin')}</span><span><strong>${e(l.city)}</strong><span>${e(l.name)}</span><small>${e(l.address)}</small></span><span class="td-radio-mark"></span></span></label>`).join('')}</div>${err('locationId')}</fieldset><div class="td-visit-grid"><fieldset><legend>Preferred date</legend>${calendar()}${err('date')}</fieldset><fieldset class="td-time-field"><legend>Time of day</legend><div class="td-periods">${Object.entries(core.periods).map(([val,text])=>`<label><input id="td-period-${val}" type="radio" name="period" value="${val}" ${state.period===val?'checked':''} ${invalid('period')}><span>${svg(val==='flexible'?'calendar':'clock')}<strong>${text}</strong><span class="td-radio-mark"></span></span></label>`).join('')}</div>${err('period')}<div class="td-visit-note">${svg('calendar')}<p>A preference, not a reserved slot. The team will confirm opening hours and availability with you.</p></div></fieldset></div>`}
 function field(label,name,type,placeholder,auto,required=true){return `<label class="td-text-field" for="td-${name}">${label}${!required?'<small>Optional</small>':''}<input id="td-${name}" name="${name}" type="${type}" value="${e(state[name])}" autocomplete="${auto}" placeholder="${placeholder}" maxlength="${name==='name'?100:150}" ${required?'required':''} ${invalid(name)}>${err(name)}</label>`}
 function detailsStage(){return `${heading('LET’S MAKE THE INTRODUCTION','How can we reach you?','A few details so the team can arrange your drive.')}<div class="td-contact-fields">${field('Your name','name','text','Full name','name')}${field('Email address','email','email','you@example.com','email')}</div><fieldset class="td-contact-preference"><legend>Preferred contact method</legend><div>${[['phone','Call me','phone'],['email','Email me','mail']].map(([key,text,icon])=>`<label><input id="td-contact-${key}" type="radio" name="contactMethod" value="${key}" ${state.contactMethod===key?'checked':''}><span>${svg(icon)}${text}<span class="td-radio-mark"></span></span></label>`).join('')}</div>${err('contactMethod')}</fieldset>${field('Phone number','phone','tel','+357 …','tel',state.contactMethod==='phone')}<label class="td-text-field" for="td-notes">Anything you’d like to ask?<small>Optional</small><textarea id="td-notes" name="notes" rows="3" maxlength="1000" placeholder="A version you’re interested in, or anything that would help us plan your visit…">${e(state.notes)}</textarea></label><label class="td-consent"><input id="td-consent" name="consent" type="checkbox" ${state.consent?'checked':''} required ${invalid('consent')}><span>I agree to be contacted about this test-drive request.</span></label>${err('consent')}<p class="td-data-note">${svg('shield')}Your details are used here to build the preview. Nothing is sent or stored.</p>`}
 function reviewCard(title,icon,step,body){return `<section class="td-review-card"><header><h3>${svg(icon)}${title}</h3>${button('Edit',`type="button" data-td-step="${step}"`,'secondary','edit')}</header>${body}</section>`}
 function reviewStage(){const m=model(),l=location();return `${heading('ONE LAST LOOK','Your drive, your way.','Check the details before previewing your request.')}<div class="td-review">${reviewCard('Your car','car',0,`<div class="td-review-model"><img src="${e(m.images[0].src)}" alt="${e(m.brand+' '+m.model)} model illustration" width="240" height="130"><div><p>${e(m.brand)}</p><strong>${e(m.model)}</strong>${m.offer?`<small>eHub reference ${e(m.reference)}</small>`:'<small>Test-drive version to be confirmed</small>'}</div></div>`)}${reviewCard('Your visit','pin',1,`<dl><div><dt>Location</dt><dd>${e(l.city)} · ${e(l.name)}<small>${e(l.address)}</small></dd></div><div><dt>Preference</dt><dd>${e(core.formatDay(state.date))}<small>${e(core.periods[state.period])} · subject to confirmation</small></dd></div></dl>`)}${reviewCard('Your details','user',2,`<dl><div><dt>Name</dt><dd>${e(state.name)}</dd></div><div><dt>Contact</dt><dd>${e(state.email)}${state.phone?`<small>${e(state.phone)}</small>`:''}<small>${state.contactMethod==='phone'?'Prefer a phone call':'Prefer an email'}</small></dd></div>${state.notes?`<div><dt>Your note</dt><dd class="td-review-notes">${e(state.notes)}</dd></div>`:''}</dl>`)}</div>`}
 function complete(){const m=model(),l=location();return `<div class="td-complete"><span class="td-complete-icon">${svg('check')}</span><p class="td-overline">YOUR REQUEST PREVIEW</p><h2 id="tdStepTitle" tabindex="-1">All set for<br>the next step.</h2><p>Your ${e(m.brand)} ${e(m.model)} request is ready to review.</p><div class="td-complete-summary"><strong>${e(m.brand+' '+m.model)}</strong><span>${e(l.city)} · ${e(l.name)}</span><span>${e(core.formatDay(state.date))} · ${e(core.periods[state.period])}</span></div><div class="td-complete-demo">${svg('shield')}<p><strong>No request has been sent.</strong>This is an interactive preview. A live booking connection is needed to send it to Unicars.</p></div><div class="td-complete-actions">${button('Edit my request','type="button" data-td-edit','secondary','edit')}<a class="button primary td-button" href="tel:+357${e(l.phone)}"><span>Call the showroom</span>${iconBox('phone')}</a></div>${button('Start a new request','type="button" data-td-restart','secondary','plus')}</div>`}
 function focusStage(root){const el=root.querySelector('#tdStepTitle');el?.focus({preventScroll:true});root.querySelector('.td-booking')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}
 function setStep(root,n){if(n>state.furthest)return;if(n>state.step){for(let i=0;i<n;i++){const errors=core.validateStep(state,i,models,locations);if(Object.keys(errors).length){state.step=i;state.errors=errors;draw(root,true);focusError(root);return}}}state.step=n;state.errors={};draw(root,true);focusStage(root)}
 function focusError(root){root.querySelector('[aria-invalid="true"]:not(:disabled)')?.focus({preventScroll:true});root.querySelector('[aria-invalid="true"]')?.closest('fieldset,label')?.scrollIntoView({block:'nearest',behavior:'smooth'})}
 function refreshModels(root){root.querySelector('#tdModels').innerHTML=modelGrid();root.querySelector('#tdMore').innerHTML=moreModels();const count=root.querySelector('#tdModelCount');if(count)count.textContent='('+core.modelChoices(models,state).length+')'}
 function bind(root){
  root.addEventListener('input',event=>{const t=event.target;if(t.id==='tdModelSearch'){state.query=t.value;state.limit=6;refreshModels(root);return}if(['name','email','phone','notes'].includes(t.name)){state[t.name]=t.value;if(state.errors[t.name]){delete state.errors[t.name];t.removeAttribute('aria-invalid');const out=root.querySelector('#td-error-'+t.name);if(out)out.textContent=''}}});
  root.addEventListener('change',event=>{const t=event.target;if(!['brand','modelId','locationId','date','period','contactMethod','consent'].includes(t.name))return;if(t.name==='brand'&&state.brand!==t.value){state.brand=t.value;state.modelId='';state.query='';state.limit=6;if(!core.eligibleLocations(locations,state.brand).some(l=>l.id===state.locationId))state.locationId='';}else if(t.name==='modelId'){state.modelId=t.value;const m=models.find(m=>m.id===t.value);state.brand=m.brand;}else state[t.name]=t.type==='checkbox'?t.checked:t.value;delete state.errors[t.name];draw(root,false,t.id||'td-phone');});
  root.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-td-step'))setStep(root,Number(b.dataset.tdStep));if(b.hasAttribute('data-td-back'))setStep(root,Math.max(0,state.step-1));if(b.hasAttribute('data-td-month')){const month=core.moveMonth(state.month,Number(b.dataset.tdMonth)),today=core.dayKey();if(month<today.slice(0,7)||month>core.addDays(today,90).slice(0,7))return;state.month=month;draw(root,false);root.querySelector('.td-calendar-nav:not(:disabled)')?.focus({preventScroll:true})}if(b.hasAttribute('data-td-clear')){state.query='';refreshModels(root);const input=root.querySelector('#tdModelSearch');input.value='';input.focus()}if(b.hasAttribute('data-td-more')){const previous=state.limit;state.limit+=6;refreshModels(root);root.querySelectorAll('.td-model-option input')[previous]?.focus({preventScroll:true})}if(b.hasAttribute('data-td-edit')){state.complete=false;state.step=3;draw(root,true);focusStage(root)}if(b.hasAttribute('data-td-restart')){state=core.freshRequest();draw(root,true);focusStage(root)}});
  root.addEventListener('submit',event=>{if(event.target.id!=='testDriveForm')return;event.preventDefault();if(state.step===3){const bad=core.firstInvalidStep(state,models,locations);if(bad){state.step=bad.step;state.errors=bad.errors;draw(root,true);focusError(root);return}state.complete=true;draw(root,true);focusStage(root);return}const errors=core.validateStep(state,state.step,models,locations);if(Object.keys(errors).length){state.errors=errors;draw(root);focusError(root);return}state.step++;state.furthest=Math.max(state.furthest,state.step);state.errors={};draw(root,true);focusStage(root)});
 }
})();
